insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-rccd-pilot-no-blind-force-s671','decision','RCCD pilot: read failing pages before forcing a re-extraction','S671: Riverside City''s forced re-extraction of 15 failing records (read 44030368835, $5.08) fixed one (31892), so Norco and Moreno Valley were not forced. A failing record''s cause is read first from the page, free, through college-page-read.yml (diagnosis 44034775728); a paid force follows only a named cause the reading can fix. #3438.',array['program-requirements','harvest','rccd','district-bot'],'proposed','S671 SkyKinglet, #3438',null,null,'SkyKinglet (S671)','2026-11-17'),
('f-rccd-area7-basic-training-s671','fact','RCCD GE Area 7 takes 2 of basic training''s 5 units','S671, college page read 44033941042: the RCCD General Education page (catalog 124, iq/5844/RCCD_Gen_Ed) lists Area 7 Lifelong Learning and Self-Development at 2 units, including HES 1 and KIN (any course with an A or V). It and the Military Credit text say five units are awarded for basic training, two toward Area 7, on an official JST or CCAF transcript. #3430, #3438.',array['program-requirements','ge','rccd','military','pathways'],'proposed','college page read 44033941042 (rccd.curriqunet.com)',null,null,'SkyKinglet (S671)','2026-11-17'),
('p-repeated-course-row-undercounts-s671','pitfall','A course printed N times is read once','S671, diagnosis read 44034775728: Riverside City Piano Performance 38626 prints MUS-P12 four times with "*Course must be taken four times"; the reading keeps one row and the blocks sum to 9.5 against the printed 18.5. Likely the same: RCC 38627, 38628, MVC 38758, Norco 30606, 30607. The lever is a shared scorer or reader change, with a second reader.',array['program-requirements','harvest','scorer','rccd'],'proposed','S671 SkyKinglet, #3438',null,null,'SkyKinglet (S671)','2026-11-17'),
('p-capture-can-lose-passing-page-s671','pitfall','A fresh capture can drop a passing record whose page it loses','S671: Riverside City read 44030368835 lost the pages of 30578 and 33829 (page_claimed, no text) and deleted their passing records from the folder; kept_passing.json covers only a re-extraction that fails. Compare the pass set before and after a read and restore lost passing records from main before a merge.',array['program-requirements','harvest','capture'],'proposed','S671 SkyKinglet, #3438',null,null,'SkyKinglet (S671)','2026-11-17')
on conflict (slug) do nothing;

